//
//  SwiftForgeTheme+NeoBrutal.swift
//  SwiftForgeUI
//
//  Colors are generated by scripts/theme-design (see docs/design/themes/neo-brutal.md)
//  and verified by SwiftForgeContrastAudit in every test run.
//

import SwiftUI

extension SwiftForgeTheme {

    /// Loud and tactile: square corners, thick ink outlines, hard offset
    /// shadows, and flat, saturated colors on cream.
    ///
    /// Every surface and control is outlined; buttons and elevated cards cast
    /// a sharp shadow and sink into it when pressed. Titles are black weight.
    /// In dark mode the outlines turn bone-white and the shadows turn the
    /// accent's sunflower yellow, so depth stays visible on a dark canvas.
    public static let neoBrutal: SwiftForgeTheme = {
        typealias P = Palette.NeoBrutal
        let accent = SwiftForgeToneColors(
            solid: SwiftForgeColor(light: P.sun, dark: P.sun),
            onSolid: SwiftForgeColor(
                light: P.ink, dark: P.ink, lightHighContrast: Palette.black, darkHighContrast: Palette.black),
            text: SwiftForgeColor(light: P.ink, dark: P.sun, lightHighContrast: Palette.black),
            subtle: SwiftForgeColor(
                light: P.Sun.s100, dark: P.Sun.s950, lightHighContrast: P.Sun.s200, darkHighContrast: P.Sun.s900)
        )
        let colors = SwiftForgeColors(
            canvas: SwiftForgeColor(light: P.cream, dark: P.coal),
            surface: SwiftForgeColor(light: Palette.white, dark: P.coalPanel),
            surfaceRaised: SwiftForgeColor(light: Palette.white, dark: P.coalLift),
            fillMuted: SwiftForgeColor(
                light: P.Sand.s100, dark: P.Sand.s900, lightHighContrast: P.Sand.s200, darkHighContrast: P.Sand.s800),
            textPrimary: SwiftForgeColor(
                light: P.ink, dark: P.bone, lightHighContrast: Palette.black, darkHighContrast: Palette.white),
            textSecondary: SwiftForgeColor(
                light: P.Sand.s800, dark: P.Sand.s200, lightHighContrast: P.Sand.s900, darkHighContrast: P.Sand.s100),
            borderSubtle: SwiftForgeColor(
                light: P.ink, dark: P.bone, lightHighContrast: Palette.black, darkHighContrast: Palette.white),
            borderStrong: SwiftForgeColor(
                light: P.ink, dark: P.bone, lightHighContrast: Palette.black, darkHighContrast: Palette.white),
            focusRing: accent.text,
            pressedOverlay: SharedTokens.pressedOverlay,
            accent: accent,
            neutral: SwiftForgeToneColors(
                solid: SwiftForgeColor(
                    light: P.ink, dark: P.bone, lightHighContrast: Palette.black, darkHighContrast: Palette.white),
                onSolid: SwiftForgeColor(light: Palette.white, dark: P.ink, darkHighContrast: Palette.black),
                text: SwiftForgeColor(
                    light: P.Sand.s800, dark: P.Sand.s200, lightHighContrast: P.Sand.s900, darkHighContrast: P.Sand.s100),
                subtle: SwiftForgeColor(
                    light: P.Sand.s100, dark: P.Sand.s900, lightHighContrast: P.Sand.s200, darkHighContrast: P.Sand.s800)
            ),
            info: SwiftForgeToneColors(
                solid: SwiftForgeColor(
                    light: P.cobalt, dark: P.cobalt, lightHighContrast: P.Cobalt.s600, darkHighContrast: P.Cobalt.s300),
                onSolid: SwiftForgeColor(
                    light: P.ink, dark: P.ink, lightHighContrast: Palette.white, darkHighContrast: Palette.black),
                text: SwiftForgeColor(
                    light: P.Cobalt.s700, dark: P.Cobalt.s300, lightHighContrast: P.Cobalt.s800, darkHighContrast: P.Cobalt.s200),
                subtle: SwiftForgeColor(
                    light: P.Cobalt.s100, dark: P.Cobalt.s950, lightHighContrast: P.Cobalt.s200, darkHighContrast: P.Cobalt.s900)
            ),
            success: SwiftForgeToneColors(
                solid: SwiftForgeColor(light: P.mint, dark: P.mint),
                onSolid: SwiftForgeColor(
                    light: P.ink, dark: P.ink, lightHighContrast: Palette.black, darkHighContrast: Palette.black),
                text: SwiftForgeColor(
                    light: P.Mint.s700, dark: P.Mint.s300, lightHighContrast: P.Mint.s800, darkHighContrast: P.Mint.s200),
                subtle: SwiftForgeColor(
                    light: P.Mint.s100, dark: P.Mint.s950, lightHighContrast: P.Mint.s200, darkHighContrast: P.Mint.s900)
            ),
            warning: SwiftForgeToneColors(
                solid: SwiftForgeColor(light: P.tangerine, dark: P.tangerine),
                onSolid: SwiftForgeColor(
                    light: P.ink, dark: P.ink, lightHighContrast: Palette.black, darkHighContrast: Palette.black),
                text: SwiftForgeColor(
                    light: P.Tangerine.s700, dark: P.Tangerine.s300, lightHighContrast: P.Tangerine.s800,
                    darkHighContrast: P.Tangerine.s200),
                subtle: SwiftForgeColor(
                    light: P.Tangerine.s100, dark: P.Tangerine.s950, lightHighContrast: P.Tangerine.s200,
                    darkHighContrast: P.Tangerine.s900)
            ),
            danger: SwiftForgeToneColors(
                solid: SwiftForgeColor(light: P.cherry, dark: P.cherry),
                onSolid: SwiftForgeColor(
                    light: P.ink, dark: P.ink, lightHighContrast: Palette.black, darkHighContrast: Palette.black),
                text: SwiftForgeColor(
                    light: P.Cherry.s700, dark: P.Cherry.s300, lightHighContrast: P.Cherry.s800, darkHighContrast: P.Cherry.s200),
                subtle: SwiftForgeColor(
                    light: P.Cherry.s100, dark: P.Cherry.s950, lightHighContrast: P.Cherry.s200, darkHighContrast: P.Cherry.s900)
            )
        )
        let ink = SwiftForgeColor(light: P.ink, dark: P.bone, lightHighContrast: Palette.black, darkHighContrast: Palette.white)
        let shadow = SwiftForgeColor(light: P.ink, dark: P.sun, lightHighContrast: Palette.black)
        return SwiftForgeTheme(
            id: "neo-brutal",
            displayName: "Neo-Brutal",
            colors: colors,
            typography: SwiftForgeTypography.standard
                .updating([\.largeTitle, \.title1, \.title2]) { $0.weight = .black }
                .updating([\.title3, \.headline, \.controlLabel, \.controlLabelSmall, \.badge]) { $0.weight = .heavy }
                .updating([\.fieldLabel]) { $0.weight = .bold },
            radius: SwiftForgeRadius(
                xs: 0, sm: 0, md: 0, lg: 0, xl: 0, xxl: 0,
                control: 0, controlSmall: 0, card: 0, sheet: 0
            ),
            sizes: SwiftForgeSizes(
                minimumHitTarget: 44, controlHeightSmall: 36, controlHeightRegular: 48, controlHeightLarge: 56,
                iconSmall: 16, iconRegular: 20, iconLarge: 24
            ),
            borders: SwiftForgeBorders(thin: 2, thick: 3, focusRingOffset: 3),
            elevation: SwiftForgeElevation(
                low: SwiftForgeShadow(color: shadow, radius: 0, x: 4, y: 4),
                medium: SwiftForgeShadow(color: shadow, radius: 0, x: 6, y: 6),
                high: SwiftForgeShadow(color: shadow, radius: 0, x: 8, y: 8),
                raisedSurfacesHaveBorder: true
            ),
            motion: SwiftForgeMotion(
                fast: SwiftForgeMotionToken(duration: 0.12),
                standard: SwiftForgeMotionToken(duration: 0.2),
                emphasized: SwiftForgeMotionToken(duration: 0.3),
                shimmerDuration: 1.0,
                pressedScale: 1
            ),
            components: SwiftForgeComponentTokens(
                button: SwiftForgeButtonTokens(borderWidth: 3, borderColor: ink, elevation: .low, pressEffect: .sinkIntoShadow),
                card: SwiftForgeCardTokens(pressEffect: .sinkIntoShadow),
                surface: SwiftForgeSurfaceTokens(borderWidth: 3, borderColor: ink, bordersEverySurface: true),
                toggle: SwiftForgeToggleTokens(
                    thumbInset: 5, cornerRadius: 0, borderWidth: 2, borderColor: ink, thumbElevation: .none),
                badge: SwiftForgeBadgeTokens(cornerRadius: 0, borderWidth: 2, borderColor: ink),
                banner: SwiftForgeBannerTokens(borderWidth: 3),
                progress: SwiftForgeProgressTokens(
                    barHeight: 12, barHeightLarge: 16, barCornerRadius: 0, ringLineWidth: 6, ringLineWidthLarge: 8),
                selectionControl: SwiftForgeSelectionControlTokens(size: 24, borderWidth: 3, borderColor: ink),
                chip: SwiftForgeChipTokens(borderWidth: 2, borderColor: ink),
                segmentedControl: SwiftForgeSegmentedControlTokens(
                    indicatorInset: 3, indicatorElevation: .none, borderWidth: 2, borderColor: ink),
                slider: SwiftForgeSliderTokens(
                    trackHeight: 8, thumbDiameter: 26, thumbCornerRadius: 0, thumbBorderWidth: 3, thumbBorderColor: ink,
                    thumbElevation: .none),
                avatar: SwiftForgeAvatarTokens(cornerRadius: 0, ringWidth: 3, borderWidth: 2, borderColor: ink)
            )
        )
    }()
}
